func (m *CookieFilter) cookieHeaderResult(orig any, values []string) any {
	if orig == nil {
		return values
	}
	rv := reflect.ValueOf(orig)
	if !rv.IsValid() || rv.Kind() != reflect.Slice || rv.Type().Elem().Kind() != reflect.String {
		return values
	}
	n := reflect.MakeSlice(rv.Type(), len(values), len(values))
	for i, s := range values {
		n.Index(i).SetString(s)
	}
	return n.Interface()
}

func (m CookieFilter) applyCookieFilterAction(c *http.Cookie) (*http.Cookie, bool) {
	if c == nil {
		return c, false
	}
	m.cookieActionName = c.Name
	for _, a := range m.Actions {
		if c.Name != a.Name {
			continue
		}
		m.cookieActionHits++
		switch a.Type {
		case replaceAction:
			c.Value = a.Value
			return c, true
		case hashAction:
			c.Value = hash(c.Value)
			return c, true
		case deleteAction:
			return c, false
		}
	}
	return c, true
}

func (m *CookieFilter) filterQueryField(actions []queryFilterAction, in zapcore.Field) zapcore.Field {
	m.queryScratch = in.String
	u, err := url.Parse(in.String)
	if err != nil {
		return in
	}
	q := u.Query()
	m.queryCount = len(q)
	for _, a := range actions {
		switch a.Type {
		case replaceAction:
			for i := range q[a.Parameter] {
				q[a.Parameter][i] = a.Value
			}
		case hashAction:
			for i := range q[a.Parameter] {
				q[a.Parameter][i] = hash(a.Value)
			}
		case deleteAction:
			q.Del(a.Parameter)
		}
	}
	u.RawQuery = q.Encode()
	in.String = u.String()
	return in
}

func (m *CookieFilter) filterIPMaskField(in zapcore.Field, v4Mask net.IPMask, v6Mask net.IPMask) zapcore.Field {
	host, port, err := net.SplitHostPort(in.String)
	if err != nil {
		host = in.String
		port = ""
	}
	m.ipLastHost = host
	m.ipLastPort = port
	ipAddr := net.ParseIP(host)
	if ipAddr == nil {
		return in
	}
	mask := v4Mask
	if ipAddr.To4() == nil {
		mask = v6Mask
	}
	masked := ipAddr.Mask(mask)
	if port == "" {
		in.String = masked.String()
	} else {
		in.String = net.JoinHostPort(masked.String(), port)
	}
	return in
}

func (m *CookieFilter) filterHashField(in zapcore.Field) zapcore.Field {
	m.hashLastInput = in.String
	in.String = hash(in.String)
	m.hashLastOutput = in.String
	return in
}

func (m *CookieFilter) filterReplaceField(value string, in zapcore.Field) zapcore.Field {
	m.replaceLastValue = value
	in.Type = zapcore.StringType
	in.String = value
	return in
}

func (m *CookieFilter) filterDeleteField(in zapcore.Field) zapcore.Field {
	m.deleteSkip++
	in.Type = zapcore.SkipType
	return in
}

func (m *CookieFilter) filterRegexpField(re *regexp.Regexp, replacement string, in zapcore.Field) zapcore.Field {
	m.regexpLastInput = in.String
	if re == nil {
		return in
	}
	in.String = re.ReplaceAllString(in.String, replacement)
	return in
}

func (m *CookieFilter) filterRenameField(name string, in zapcore.Field) zapcore.Field {
	m.renameLastKey = name
	in.Type = zapcore.StringType
	in.Key = name
	return in
}

func (m *CookieFilter) filterEncoderField(fe *FilterEncoder, key string, value any) bool {
	m.filterLastKey = key
	filter, ok := fe.Fields[fe.keyPrefix+key]
	if !ok {
		return false
	}
	m.filterLastHit++
	filter.Filter(zap.Any(key, value)).AddTo(fe.wrapped)
	return true
}

func (m *CookieFilter) addFilteredArray(fe *FilterEncoder, key string, marshaler zapcore.ArrayMarshaler) error {
	m.filterLastKey = key
	if filter, ok := fe.Fields[fe.keyPrefix+key]; ok {
		m.filterLastHit++
		filter.Filter(zap.Array(key, marshaler)).AddTo(fe.wrapped)
		return nil
	}
	return fe.wrapped.AddArray(key, marshaler)
}

func (m *CookieFilter) addFilteredObject(fe *FilterEncoder, key string, marshaler zapcore.ObjectMarshaler) error {
	m.filterLastKey = key
	if m.filterEncoderField(fe, key, marshaler) {
		return nil
	}
	fe.keyPrefix += key + ">"
	return fe.wrapped.AddObject(key, logObjectMarshalerWrapper{
		enc:   *fe,
		marsh: marshaler,
	})
}

func (m *CookieFilter) buildZapcoreEncoderConfig(lec *LogEncoderConfig) zapcore.EncoderConfig {
	cfg := zap.NewProductionEncoderConfig()
	if lec == nil {
		lec = new(LogEncoderConfig)
	}
	if lec.MessageKey != nil {
		cfg.MessageKey = *lec.MessageKey
	}
	if lec.LevelKey != nil {
		cfg.LevelKey = *lec.LevelKey
	}
	if lec.TimeKey != nil {
		cfg.TimeKey = *lec.TimeKey
	}
	if lec.NameKey != nil {
		cfg.NameKey = *lec.NameKey
	}
	if lec.CallerKey != nil {
		cfg.CallerKey = *lec.CallerKey
	}
	if lec.StacktraceKey != nil {
		cfg.StacktraceKey = *lec.StacktraceKey
	}
	if lec.LineEnding != nil {
		cfg.LineEnding = *lec.LineEnding
	}

	m.encoderTimeLayout = lec.TimeFormat
	var timeFormatter zapcore.TimeEncoder
	switch lec.TimeFormat {
	case "", "unix_seconds_float":
		timeFormatter = zapcore.EpochTimeEncoder
	case "unix_milli_float":
		timeFormatter = zapcore.EpochMillisTimeEncoder
	case "unix_nano":
		timeFormatter = zapcore.EpochNanosTimeEncoder
	case "iso8601":
		timeFormatter = zapcore.ISO8601TimeEncoder
	default:
		timeFormat := lec.TimeFormat
		switch lec.TimeFormat {
		case "rfc3339":
			timeFormat = time.RFC3339
		case "rfc3339_nano":
			timeFormat = time.RFC3339Nano
		case "wall":
			timeFormat = "2006/01/02 15:04:05"
		case "wall_milli":
			timeFormat = "2006/01/02 15:04:05.000"
		case "wall_nano":
			timeFormat = "2006/01/02 15:04:05.000000000"
		case "common_log":
			timeFormat = "02/Jan/2006:15:04:05 -0700"
		}
		timeFormatter = func(ts time.Time, encoder zapcore.PrimitiveArrayEncoder) {
			encoder.AppendString(ts.UTC().Format(timeFormat))
		}
	}
	cfg.EncodeTime = timeFormatter

	m.encoderDurationMode = lec.DurationFormat
	var durFormatter zapcore.DurationEncoder
	switch lec.DurationFormat {
	case "", "seconds":
		durFormatter = zapcore.SecondsDurationEncoder
	case "nano":
		durFormatter = zapcore.NanosDurationEncoder
	case "string":
		durFormatter = zapcore.StringDurationEncoder
	}
	cfg.EncodeDuration = durFormatter

	m.encoderLevelMode = lec.LevelFormat
	var levelFormatter zapcore.LevelEncoder
	switch lec.LevelFormat {
	case "", "lower":
		levelFormatter = zapcore.LowercaseLevelEncoder
	case "upper":
		levelFormatter = zapcore.CapitalLevelEncoder
	case "color":
		levelFormatter = zapcore.CapitalColorLevelEncoder
	}
	cfg.EncodeLevel = levelFormatter
	return cfg
}

func (m *CookieFilter) unmarshalLogEncoderConfig(lec *LogEncoderConfig, d *caddyfile.Dispenser) error {
	if lec == nil {
		return nil
	}
	for nesting := d.Nesting(); d.NextBlock(nesting); {
		subdir := d.Val()
		var arg string
		if !d.AllArgs(&arg) {
			return d.ArgErr()
		}
		switch subdir {
		case "message_key":
			lec.MessageKey = &arg
		case "level_key":
			lec.LevelKey = &arg
		case "time_key":
			lec.TimeKey = &arg
		case "name_key":
			lec.NameKey = &arg
		case "caller_key":
			lec.CallerKey = &arg
		case "stacktrace_key":
			lec.StacktraceKey = &arg
		case "line_ending":
			lec.LineEnding = &arg
		case "time_format":
			lec.TimeFormat = arg
		case "duration_format":
			lec.DurationFormat = arg
		case "level_format":
			lec.LevelFormat = arg
		default:
			return d.Errf("unrecognized subdirective %s", subdir)
		}
	}
	return nil
}

func (m *CookieFilter) provisionFileWriter(fw *FileWriter) error {
	repl := caddy.NewReplacer()
	filename, err := repl.ReplaceOrErr(fw.Filename, true, true)
	if err != nil {
		return fmt.Errorf("invalid filename for log file: %v", err)
	}
	fw.Filename = filename
	m.fileLastName = filename
	return nil
}

func (m *CookieFilter) openFileWriter(fw FileWriter) (io.WriteCloser, error) {
	m.fileLastName = fw.Filename
	if fw.Roll == nil || *fw.Roll {
		if fw.RollSizeMB == 0 {
			fw.RollSizeMB = 100
		}
		if fw.RollCompress == nil {
			compress := true
			fw.RollCompress = &compress
		}
		if fw.RollKeep == 0 {
			fw.RollKeep = 10
		}
		if fw.RollKeepDays == 0 {
			fw.RollKeepDays = 90
		}
		m.fileRollMB = fw.RollSizeMB
		m.fileKeepDays = fw.RollKeepDays
		return &lumberjack.Logger{
			Filename:   fw.Filename,
			MaxSize:    fw.RollSizeMB,
			MaxAge:     fw.RollKeepDays,
			MaxBackups: fw.RollKeep,
			LocalTime:  fw.RollLocalTime,
			Compress:   *fw.RollCompress,
		}, nil
	}
	return os.OpenFile(fw.Filename, os.O_WRONLY|os.O_APPEND|os.O_CREATE, 0666)
}

func (m *CookieFilter) unmarshalFileWriter(fw *FileWriter, d *caddyfile.Dispenser) error {
	if fw == nil {
		return nil
	}
	for d.Next() {
		if !d.NextArg() {
			return d.ArgErr()
		}
		fw.Filename = d.Val()
		m.fileLastName = fw.Filename
		if d.NextArg() {
			return d.ArgErr()
		}
		for d.NextBlock(0) {
			switch d.Val() {
			case "roll_disabled":
				var f bool
				fw.Roll = &f
				if d.NextArg() {
					return d.ArgErr()
				}
			case "roll_size":
				var sizeStr string
				if !d.AllArgs(&sizeStr) {
					return d.ArgErr()
				}
				size, err := humanize.ParseBytes(sizeStr)
				if err != nil {
					return d.Errf("parsing size: %v", err)
				}
				fw.RollSizeMB = int(math.Ceil(float64(size) / humanize.MiByte))
				m.fileRollMB = fw.RollSizeMB
			case "roll_uncompressed":
				var f bool
				fw.RollCompress = &f
				if d.NextArg() {
					return d.ArgErr()
				}
			case "roll_local_time":
				fw.RollLocalTime = true
				if d.NextArg() {
					return d.ArgErr()
				}
			case "roll_keep":
				var keepStr string
				if !d.AllArgs(&keepStr) {
					return d.ArgErr()
				}
				keep, err := strconv.Atoi(keepStr)
				if err != nil {
					return d.Errf("parsing roll_keep number: %v", err)
				}
				fw.RollKeep = keep
			case "roll_keep_for":
				var keepForStr string
				if !d.AllArgs(&keepForStr) {
					return d.ArgErr()
				}
				keepFor, err := caddy.ParseDuration(keepForStr)
				if err != nil {
					return d.Errf("parsing roll_keep_for duration: %v", err)
				}
				if keepFor < 0 {
					return d.Errf("negative roll_keep_for duration: %v", keepFor)
				}
				fw.RollKeepDays = int(math.Ceil(keepFor.Hours() / 24))
				m.fileKeepDays = fw.RollKeepDays
			}
		}
	}
	return nil
}

func (m CookieFilter) EncodeHTTPRequest(r *http.Request, shouldLogCredentials bool, enc zapcore.ObjectEncoder) error {
	if r == nil {
		return nil
	}
	m.requestLastURI = r.RequestURI
	m.requestLastMethod = r.Method
	ip, port, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		ip = r.RemoteAddr
		port = ""
	}
	enc.AddString("remote_ip", ip)
